(()=>{document.addEventListener('DOMContentLoaded',()=>{const cloud=WildRideMember.mode==='supabase';document.querySelectorAll('[data-google-login]').forEach(b=>{b.addEventListener('click',async()=>{b.disabled=true;try{if(!cloud)throw Error('本機預覽仍使用本機會員服務。上線版本提供 Google 登入；雲端測試可將 localPreview 設為 false。');await WildRideMember.signInWithGoogle()}catch(e){const feedback=document.getElementById('member-message')||document.getElementById('ops-status');if(feedback){feedback.textContent=e.message;feedback.classList.add('error')}}finally{b.disabled=false}})});if(!cloud)return;const replacements=[['本機會員測試版','雲端會員測試版'],['本機功能測試版','雲端功能測試版'],['本機會員服務','Supabase 雲端會員服務'],['學院本機測試服務','Supabase 雲端服務'],['尚未部署為對外服務。',''],['Email 尚未驗證。資料僅用於','請依收到的驗證信完成驗證。資料僅用於'],['目前未提供 Email 驗證、寄信找回密碼或第三方登入。測試時請使用專用密碼。','支援 Email 註冊與 Google 登入。Email 註冊後請依驗證信完成啟用；Google 登入需先完成學院 OAuth 設定。'],['目前為本機測試帳號，','目前為學院測試帳號，'],['完成後會登出該會員的所有裝置。','原有登入權限的完整撤銷依 Supabase 工作階段與 JWT 有效期生效。']];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(['SCRIPT','STYLE'].includes(n.parentElement.tagName))continue;for(const[a,b]of replacements)n.textContent=n.textContent.replaceAll(a,b)}document.querySelectorAll('a[href^="/api/certificates/"]').forEach(a=>{const id=a.getAttribute('href').split('/')[3];a.href=WildRideMember.certificateUrl(id)})})})();
